/// A headless journey runner: render `current` however you like, then call `complete` with what the
/// customer did. It records document and consent evidence, stores fields, prefills, starts hosted actions
/// (returning where to send the customer) and follows the journey's branches.
public final class JourneyRunner {
    public let journey: JSON
    public private(set) var current: JSON?
    private let client: MyntClient
    private let product: String
    private let steps: [String: JSON]

    public init(client: MyntClient, journeyId: String) async throws {
        self.client = client
        journey = try await client.journey(journeyId)
        product = (journey["built_on"] as? JSON)?["product_id"] as? String ?? ""
        let list = journey["steps"] as? [JSON] ?? []
        var byId: [String: JSON] = [:]
        for s in list { if let id = s["id"] as? String { byId[id] = s } }
        steps = byId
        current = list.first
    }

    public var done: Bool {
        guard let s = current else { return true }
        return s["next"] == nil && s["on"] == nil && s["action"] == nil && s["capture_consent"] == nil && s["await_event"] == nil
    }

    private func go(_ id: String?) { current = id.flatMap { steps[$0] } }

    private func branch(_ step: JSON, _ outcome: String?) -> String? {
        if let outcome = outcome, let next = (step["on"] as? [String: String])?[outcome] { return next }
        return step["next"] as? String
    }

    /// Completes the current step; for a hosted action, returns where to send the customer.
    @discardableResult
    public func complete(_ input: StepInput = StepInput()) async throws -> String? {
        guard let step = current else { throw MyntError(status: 0, code: "journey_ended", message: "The journey has ended") }
        if let purpose = step["capture_consent"] as? String {
            guard let text = input.consentText else { throw MyntError(status: 0, code: "consent_text", message: "Pass the consent wording the customer agreed to") }
            _ = try await client.giveConsent(product, purpose: purpose, consentText: text)
            go(branch(step, nil))
            return nil
        }
        if let action = step["action"] as? String {
            if input.outcome != nil {
                go(branch(step, input.outcome))
                return nil
            }
            return try await client.startAction(product, action: action)["redirect_url"] as? String
        }
        if step["await_event"] != nil {
            go(branch(step, input.outcome))
            return nil
        }
        let elements = step["screen"] as? [JSON] ?? []
        for e in elements where e["type"] as? String == "disclosure" {
            let document = e["document"] as? String ?? ""
            guard let text = input.documents[document] else { throw MyntError(status: 0, code: "document_text", message: "Pass the text shown for document " + document) }
            _ = try await client.documentShown(product, document: document, shownText: text)
        }
        let fields = elements.filter { $0["type"] as? String == "field" }
        for source in ["typed", "secure_field", "document_upload"] {
            var values: JSON = [:]
            for f in fields where (f["capture"] as? String ?? "typed") == source {
                if let name = f["field"] as? String, let value = input.fields[name] { values[name] = value }
            }
            if !values.isEmpty { _ = try await client.saveFields(product, values: values, source: source) }
        }
        for source in ["account_aggregator", "digilocker", "ckyc"] {
            let wanted = fields.filter { ($0["capture"] as? String) == source && input.fields[$0["field"] as? String ?? ""] == nil }.compactMap { $0["field"] as? String }
            if !wanted.isEmpty { _ = try await client.prefill(product, source: source, fields: wanted) }
        }
        go(branch(step, input.outcome))
        return nil
    }
}
